package indoor.localization

enum class PositionSource { PDR, VISUAL, FUSED }

/** Which map location a resolved anchor represents; both use the same map axes and origin. */
enum class PositionReference { MEASUREMENT_RAW, NAVIGATION }

/**
 * x/y: meters in floor2_map.json axes. heading: magnetic-north clockwise degrees [0, 360),
 * null when unknown. Do not apply the guideline's illustrative +Y=0 convention to this map.
 * timestamp: Unix epoch milliseconds, supplied by an adapter (never generated by this model).
 * confidence: [0, 1], whose calibration is the producing algorithm's responsibility.
 * nodeId: optional anchor association; PDR need not be located on a node.
 */
data class PositionEstimate(
    val x: Double,
    val y: Double,
    val floor: Int,
    val heading: Double?,
    val confidence: Double,
    val timestamp: Long,
    val source: PositionSource,
    val positionReference: PositionReference,
    val nodeId: String? = null,
) {
    init {
        require(x.isFinite() && y.isFinite()) { "Coordinates must be finite" }
        require(heading == null || (heading.isFinite() && heading >= 0 && heading < 360)) { "Invalid heading" }
        require(confidence.isFinite() && confidence in 0.0..1.0) { "Invalid confidence" }
        require(timestamp >= 0) { "timestamp must be Unix milliseconds >= 0" }
        require(nodeId == null || nodeId.isNotBlank()) { "nodeId must not be blank" }
    }
}
